begin;
on conflict(entity_key) do update set name=excluded.name,category=excluded.category,relationship=excluded.relationship;
on conflict(entity_key,source) do update set source_url=excluded.source_url,property_id=excluded.property_id,warning=excluded.warning,provenance=excluded.provenance;
on conflict(source,property_id) do update set property_name=excluded.property_name,hotel_key=excluded.hotel_key,source_url=excluded.source_url;
commit;
select category,relationship,count(*) as locations from public.review_tracker_directory group by category,relationship order by relationship,category;
